B.bdp=new A.rk("Koordinaten auf der Karte","location_on",B.dv,B.c8w,null)
B.bdm=new A.jo('Manche Forstbetriebe (vor allem kleinere) liefern keine ELDAT-Daten. In diesem Fall kannst du einen Polter \xfcber den "Manuelle Lieferung anlegen"-Bereich vollst\xe4ndig per Hand erfassen.',null)
B.bdh=new A.jo("Du gibst dann alle Daten direkt ein: Polter-Nummer, Forstamt, Forstrevier, Betrieb, Holzart-Mengen, Standort \xfcber die Karte. Der angelegte Polter verh\xe4lt sich danach genauso wie ein importierter \u2014 Fuhrmann-Zuweisung, Status, alles gleich.",null)
B.Ea=new A.a5r(1,"warning")
B.dhL=new A.p4("Bitte alle Pflichtfelder sorgf\xe4ltig ausf\xfcllen. Falsche Holzart-Zuordnungen lassen sich sp\xe4ter nur schwer korrigieren, weil sie sich auf den gesamten Bestand auswirken.",B.Ea,null)
B.c93=s([B.bdm,B.bdh,B.dhL],t.p)
